#include<stdio.h>
#include<stdlib.h>

struct Node{
    int data;
    struct Node* prev;
    struct Node* next;
};

struct Node* createNode(int value){
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->prev = NULL;
    newNode->next = NULL;

    return newNode;
}

struct Node* insertAtBeginning(struct Node* head , int value){
    struct Node* newNode = createNode(value);

    if(head == NULL){
        return newNode;
    }

    newNode->next = head;
    head->prev = newNode;
    return newNode;

}

struct Node* insertEnd(struct Node* head , int value){
    struct Node* newNode = createNode(value);
    if(head == NULL){
        return newNode;
    }

    struct Node* temp = head;
    while(temp->next != NULL){
        temp = temp->next;
    }

    temp->next = newNode;
    newNode->prev = temp;

    return head;

}

void displayForward(struct Node* head){
    if(head == NULL){
        printf("empty list");
    }

    struct Node* temp = head;

    while(temp != NULL){
        printf("%d",temp->next);
        temp = temp->next;
    }

}

int main(){
    struct Node* head = NULL;

    head = insertAtBeginning(head,20);
    head = insertAtBeginning(head,50);
    displayForward(head);
    return 0;
}

Alright — good start, but there’s one clear issue that’s breaking your `displayForward()` output.  

Here’s what’s wrong:  
Inside `displayForward()`, you wrote  
```c
printf("%d", temp->next);
```
That prints the **address** of the next node (a pointer), not the **data**.  
You need to print `temp->data` instead.

Also, your `displayForward()` should print something more readable (like spaces or arrows), and it’s good practice to add a newline at the end.

Here’s the **fixed and clean version** of your code:

```c
#include<stdio.h>
#include<stdlib.h>

struct Node {
    int data;
    struct Node* prev;
    struct Node* next;
};

struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

struct Node* insertAtBeginning(struct Node* head, int value) {
    struct Node* newNode = createNode(value);

    if (head == NULL)
        return newNode;

    newNode->next = head;
    head->prev = newNode;
    return newNode;
}

struct Node* insertEnd(struct Node* head, int value) {
    struct Node* newNode = createNode(value);
    if (head == NULL)
        return newNode;

    struct Node* temp = head;
    while (temp->next != NULL) {
        temp = temp->next;
    }

    temp->next = newNode;
    newNode->prev = temp;

    return head;
}

void displayForward(struct Node* head) {
    if (head == NULL) {
        printf("Empty list\n");
        return;
    }

    struct Node* temp = head;
    printf("List (forward): ");
    while (temp != NULL) {
        printf("%d ", temp->data);
        temp = temp->next;
    }
    printf("\n");
}

int main() {
    struct Node* head = NULL;

    head = insertAtBeginning(head, 20);
    head = insertAtBeginning(head, 50);
    head = insertEnd(head, 70);

    displayForward(head);

    return 0;
}
```

✅ **Output:**
```
List (forward): 50 20 70
```

